import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第五卷 答案 · 第109章 动笔","description":"","frontmatter":{},"headers":[],"relativePath":"第109章_动笔.md","filePath":"第109章_动笔.md"}'),r={name:"第109章_动笔.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第五卷-答案-·-第109章-动笔" tabindex="-1">第五卷 答案 · 第109章 动笔 <a class="header-anchor" href="#第五卷-答案-·-第109章-动笔" aria-label="Permalink to &quot;第五卷 答案 · 第109章 动笔&quot;">​</a></h1><p>夜市散场后的后街很安静，风里还留着炒面的焦香。 我把小桌上的碗叠好，奶奶那碗糖水只喝了一半，温棠说明天热一下还能喝，我点点头，没有说话。 周野蹲在路灯下系鞋带，抬头看我一眼，说今晚还回老街吗。 我说回，奶奶一个人在家，我不放心。 顾远把打包好的炒粉塞进我手里，说带回去当夜宵，半夜饿了热一热。 温棠站在雾气里，怀里抱着那只旧布包，忽然问我，那本小说，你还打算送出去吗。 我摄了摇头，说她阿婆病倒了，先缓一缓。 她哦了一声，没有再问。</p><p>回到老街时，巷子里的狗叫了一声，又安静下去。 奶奶睡得很沉，呼吸声很轻，床头放着半杯水，还有她白天叠了一半的纸星星，不计那27颗。 我把灯调暗，坐在窗边的小凳上，把桌上的铁盒拿过来。 盒子里是江苒留下的纸星星，我数过很多遍，一共二十七颗。之后再出现的那一颗，是二十七颗之外她新折的，另算。 每一颗都折得很紧，棱角分明，颜色早就褪了，粉的发了白，蓝的像阴天的湖。 我把它们一颗一颗倒出来，在桌上排成三排。 窗外的蛐蛐叫得很密，铁皮屋顶偶尔被风吹得响一下。</p><p>随身听放在桌角，磁带还在里面，没有拿出来。 我戴上耳机，按下播放键，里面是空白的沙沙声，听久了，反而让人心定。 以前我总觉得，故事要从最大的那件事讲起，后来才明白，真正能留住人的，是最小的东西。 比如一颗纸星星，比如一句没说完的话。</p><p>温棠在夜市上说的那句话，一直在我脑子里转。 她问我，沈聿，你要是动笔，你第一句写什么。 我说我不知道。 她说，你肯定知道，你只是不敢写。 周野在旁边笑，说你别逼他，他这人，嘴比蚌壳还紧。 温棠推了周野一把，说你懂什么，有些话，写出来比说出来难多了。 我当时低头喝糖水，甜味在舌尖化开，喉咙却有点发紧。 我说，等我把星星整理完，我就动笔。</p><p>现在，星星就在眼前。 我找来一个本子，是南雾老乡聚餐时顾远送的，封皮上印着雾山大学的湖，空白页，很厚。 我翻开第一页，手悬了很久，笔尖都没落下去。 奶奶在梦里翻了个身，含糊地喊了一声，我的名字，尾音拖得很长。 我赶紧过去给她掖被子，她的手很烫，我用毛巾给她擦了擦额头。 她闭着眼说，聿聿，别熬夜。 我说好，我就坐一会儿。 她又睡过去了。</p><p>我回到桌边，深吸一口气，空气里有药味，有旧木头的味道，还有纸星星上淡淡的霉味。 我拿起第一颗粉色的星星，对着灯看了看，纸的折缝里藏着一点灰。 我想起江苒折星星的样子，她总喜欢在上课前折，手指很快，眼睛却看着窗外。 有一次我问她，你折这么多，许的什么愿。 她说不能说，说出来就不灵了。 我说那你折完送谁。 她笑了笑，说送给一个以后会写故事的人。 当时我没懂，现在想起来，心口像被什么轻轻撞了一下。</p><p>我在本子上写下，第一颗，粉色，起笔。 笔尖划过纸面，发出很细的声响。 我写，她把愿望折进星里，却把钥匙留给了我。 写完这一句，我停下来，看了很久。 原来动笔并没有想象中那么难，难的是承认，每一颗星星背后，都是一章没写完的我们。</p><p>我拿起第二颗，是蓝色的，角有点压扁了。 我想起后街那场雨，我和她躲在小桌的棚子下，雨水顺着塑料布往下流，炒面师傅还在翻锅，香气混着雨气扑过来。 她把外套分我一半，肩膀靠着肩膀，谁也没有动。 磁带里的歌放到一半卡住了，发出吱的一声，她笑出声，说这随身听，比我们俩还倔。 我写下，第二颗，蓝色，雨夜的棚子。 我发现，只要盯着一颗星星看，画面自己会浮上来，根本拦不住。</p><p>第三颗是黄色的，颜色最亮。 那是平安结被退回来的那天。 我到现在还记得那个纸袋的触感，很轻，却像一块石头。 她没有哭，只是把纸袋推回来，说这个，先放你那吧。 我说了好，嗓子哑得不像自己的。 那天晚上我一个人在操场走了很久，塑胶跑道的味道很浓，脚步声在空荡里格外清楚。 我把这段写下来的时候，手有点抖。 我写，第三颗，黄色，有些东西退回来，人就散了。</p><p>写到第五颗的时候，手机震了一下。 是周野发来的消息，他说，兄弟，睡了吗。 我说没，在整理星星。 他说，需要帮忙吗，我明天带炒面过去。 我说不用，奶奶睡了，别吵。 他发了个表情，又补了一句，你要是写不下去，就先睡觉，别硬扛。 我回了个好字，眼睛却有点热。 在这个雾气很重的城市里，能有人半夜问你睡了吗，本身就是一种糖水，甜得不腻。</p><p>温棠发来一条，说她到家了，路上想起一句话要带给我：星星不用全拆开，留几颗完整的，当锚。 我问，什么锚。 她说，船的锚，故事的锚，人走远了，锚还在，就不会丢。 我看着桌上那二十七颗星星，忽然明白了温棠的意思。 每一颗，都是一章。 每一章，都是一个锚点。 我不需要一次把海走完，我只需要，把锚一个一个放下去。</p><p>我把本子翻到新的一页，写下目录两个字。 然后一颗一颗地数，一颗一颗地记。 第一颗，初见的糖水。 第二颗，雨夜的棚子。 第三颗，被退回的平安结。 写到第十颗的时候，奶奶咳嗽了一声，我起身给她倒水，扶她喝下，又看她躺好。 她迷迷糊糊地说，你在写啊。 我说嗯，随便写写。 她说，写吧，写出来，心里就不闷了。 我说好。 她拉着我的衣角，很快又睡着了，手却没松开。</p><p>我坐回去，继续写。 夜越来越深，蛐蛐声小了，风从门缝进来，吹得纸星星轻轻晃。 随身听里的沙沙声还在，像海浪，一阵一阵的。 我写到第二十颗，笔有些没水了，换了一支，墨色深了一些，正好，像心情沉下去了一点。 顾远的声音忽然在脑子里响起来，他在夜市上说，沈聿，你这人就是太闷了，半留守的孩子都这样吗，跟着奶奶住久了，心事都存着。 我当时笑骂了他一句，心里却记住了。 是啊，我跟奶奶住在旧楼，日子是静的，心事是存着的。 存久了，就成了星星，硬硬的，硌手。</p><p>第二十三颗，是一颗白色的，折得很小。 我把灯凑近看，才发现纸的内侧有一点字迹，被折进去了，看不清。 我心里一动，想拆开，又停住了。 温棠说，留几颗完整的，当锚。 可是这颗，里面好像藏着话。 我把它单独放在一边，手指在上面摩挲了很久。 纸面粗糙的触感，顺着指尖传上来，让我想起江苒的手，冬天总是凉的，她喜欢把手揣进我的袖子里，理直气壮地说，借个暖。 我写下，第二十三颗，白色，未拆。 有些话，还是先留着吧。</p><p>写到第二十七颗的时候，天边已经有点发灰了。 巷子口有了动静，是早点摊在摆锅，铁器相碰的声音，伴着油香飘进来。 我数了数本子上的目录，正好二十七行。 每一行都很短，短到只有我自己能看懂。 可是看着它们，我忽然觉得，这本书有了骨头。 不再是飘着的，不再是缓一缓的借口。 它是锚，是二十七个锚，沉甸甸地坠着我，不让我再漂。</p><p>我把星星重新收进铁盒，只留下那颗白色的，那是二十七颗之中的第二十三颗，放在本子上面。 奶奶醒了，声音很哑，喊我喝水。 我把水递过去，她喝了一口，看着桌上的本子，笑了。 她说，动笔了。 我说，动笔了。 她说，好，好孩子。 我鼻子一酸，赶紧低头收笔，怕她看见。</p><p>手机又震了一下，是温棠。 她说，沈聿，你猜我昨晚梦见什么了。 我说什么。 她说，我梦见你把星星全拆了，一颗里面一张纸条，拼起来是一封信。 我看着那颗白色的星星，心跳忽然快起来。 我问，那信上写了什么。 她过了很久才回，只有四个字。 她说，等我问你。 我盯着那四个字，又看了看桌上那颗没拆的星星，手指悬在半空，迟迟没有落下去。 门外，巷子里的脚步声停住了，很轻，很熟悉，像是停在了我家门口。</p>',18)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
